<?php
require 'includes/core.php';$u=require_logged_in();$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){csrf();$action=$_POST['action']??'read_all';if($action==='read_one'){$id=(int)($_POST['id']??0);$q=$pdo->prepare('UPDATE notifications SET read_at=NOW() WHERE user_id=? AND id=? AND read_at IS NULL');$q->execute([$u['id'],$id]);}elseif($action==='read_all'){$q=$pdo->prepare('UPDATE notifications SET read_at=NOW() WHERE user_id=? AND read_at IS NULL');$q->execute([$u['id']]);}notify('Notificações atualizadas.');go('notifications.php');}
$filter=$_GET['filter']??'unread';if(!in_array($filter,['unread','all'],true))$filter='unread';
$sql='SELECT * FROM notifications WHERE user_id=?'.($filter==='unread'?' AND read_at IS NULL':'').' ORDER BY created_at DESC LIMIT 100';$q=$pdo->prepare($sql);$q->execute([$u['id']]);$rows=$q->fetchAll();$unread=unread_count($u['id']);
layout_start('Central de notificações',$u);?>
<section class="control-head"><div><span class="kicker">CENTRAL DE AVISOS</span><h1>Notificações</h1><p class="muted">Avisos dos seus atendimentos, organizados por importância.</p></div><?php if($u['role']==='admin'):?><a class="btn secondary" href="<?=url('admin/dashboard.php')?>">Voltar ao painel</a><?php endif;?></section>
<div class="notice-top"><div class="control-filters"><a class="<?=$filter==='unread'?'selected':''?>" href="?filter=unread">Não lidas (<?=$unread?>)</a><a class="<?=$filter==='all'?'selected':''?>" href="?filter=all">Histórico</a></div><form method="post"><input type="hidden" name="csrf" value="<?=token()?>"><input type="hidden" name="action" value="read_all"><button class="btn secondary" <?=$unread===0?'disabled':''?>>Marcar todas como lidas</button></form></div>
<div class="notice-stack"><?php foreach($rows as $r):?><?php $important=(bool)preg_match('/urgente|prioridade|novo chamado|resposta/i',$r['title'].' '.$r['body']);?><article class="notice-card <?= $r['read_at']?'':'is-new' ?>"><div class="notice-symbol"><?=$important?'!':'●'?></div><div class="notice-info"><div class="notice-card-title"><strong><?=h($r['title'])?></strong><?php if($important):?><span class="notice-tag">Atenção</span><?php endif;?></div><p><?=h($r['body'])?></p><small class="muted"><?=date('d/m/Y H:i',strtotime($r['created_at']))?></small></div><div class="notice-actions"><a href="<?=url('notification-open.php?id='.$r['id'])?>" class="btn">Abrir aviso</a><?php if(!$r['read_at']):?><form method="post"><input type="hidden" name="csrf" value="<?=token()?>"><input type="hidden" name="action" value="read_one"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="btn secondary">Marcar lida</button></form><?php endif;?></div></article><?php endforeach;?><?php if(!$rows):?><div class="card empty-notice">Nenhuma notificação nesta categoria.</div><?php endif;?></div>
<?php layout_end();?>